// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // bound v to avoid overflow issues
        v = bound(v, 0, 1e30);
        // Ensure _tos is not empty and has reasonable length
        vm.assume(_tos.length > 0 && _tos.length <= 10);
        // Avoid sender being zero address to prevent potential reverts
        vm.assume(from != address(0));
        // Drive the call
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));
        if (success) {
            bool retVal = abi.decode(data, (bool));
            assertTrue(retVal == true, "transfer must return true when it does not revert");
        }
    }
}

